115→    async fn fetch_history(
116→        &self,
117→        wallet: &str,
118→        limit: usize,
119→        user_id: Uuid,
120→        checkpoint: Option<&IndexerCheckpoint>,
121→    ) -> anyhow::Result<Vec<Transaction>> {
