131→            latest_block.saturating_sub(total_blocks)
132→        };
133→
134→        let logs = self.fetch_logs(address, from_block, latest_block).await?;
135→
136→        // Collect unique tx hashes so we can fetch receipts/transactions once per hash
137→        let mut seen_tx_hashes: HashMap<String, (serde_json::Value, serde_json::Value)> =
138→            HashMap::new();
139→
140→        for log in &logs {
141→            let tx_hash_b256 = match log.transaction_hash {
142→                Some(h) => h,
143→                None => continue,
144→            };
145→            let tx_hash = format!("{tx_hash_b256:#x}");
146→
147→            if seen_tx_hashes.contains_key(&tx_hash) {
148→                continue;
149→            }
150→
151→            // Fetch transaction details (value, from, to) and receipt (gas_used, effective_gas_price)
152→            let mut tx_fields = json!({});
153→            let mut receipt_fields = json!({});
154→
155→            self.rate_limiter.until_ready().await;
156→            match self.provider.get_transaction_by_hash(tx_hash_b256).await {
157→                Ok(Some(full_tx)) => {
158→                    let value = full_tx.inner.value();
159→                    let from = full_tx.inner.signer();
160→                    let to = full_tx.inner.to().map(|a| format!("{a:#x}"));
161→                    tx_fields = json!({
162→                        "value": format!("{value:#x}"),
163→                        "from": format!("{from:#x}"),
164→                        "to": to,
165→                    });
166→                }
167→                Ok(None) => {}
168→                Err(e) => {
169→                    warn!(tx_hash = %tx_hash, error = %e, "Failed to fetch transaction");
170→                }
171→            }
172→
173→            self.rate_limiter.until_ready().await;
174→            match self.provider.get_transaction_receipt(tx_hash_b256).await {
175→                Ok(Some(receipt)) => {
176→                    receipt_fields = json!({
177→                        "gas_used": format!("{:#x}", receipt.gas_used),
178→                        "effective_gas_price": format!("{:#x}", receipt.effective_gas_price),
179→                    });
180→                }
181→                Ok(None) => {}
182→                Err(e) => {
183→                    warn!(tx_hash = %tx_hash, error = %e, "Failed to fetch receipt");
184→                }
185→            }
186→
187→            seen_tx_hashes.insert(tx_hash, (tx_fields, receipt_fields));
188→        }
189→
190→        let mut transactions = Vec::new();
191→        let mut emitted_tx_hashes = HashSet::new();
192→
193→        for log in &logs {
194→            let tx_hash = match log.transaction_hash {
195→                Some(h) => format!("{h:#x}"),
196→                None => continue,
197→            };
198→
199→            let block_timestamp = log.block_timestamp.unwrap_or(0);
200→
201→            let mut raw_metadata = json!({
202→                "log_index": log.log_index,
203→                "block_number": log.block_number,
204→                "block_hash": log.block_hash.map(|h| format!("{h:#x}")),
205→                "transaction_hash": &tx_hash,
206→                "address": format!("{:#x}", log.address()),
207→                "topics": log.topics().iter().map(|t| format!("{t:#x}")).collect::<Vec<_>>(),
208→                "data": format!("0x{}", alloy::hex::encode(log.data().data.as_ref())),
209→            });
210→
211→            // Only attach tx-level fields (value, from, to, gas_used, effective_gas_price)
212→            // to the first log per tx hash to avoid duplicate gas fee / value entries.
213→            let is_first_log = emitted_tx_hashes.insert(tx_hash.clone());
214→            if is_first_log {
215→                if let Some((tx_fields, receipt_fields)) = seen_tx_hashes.get(&tx_hash) {
216→                    if let Some(obj) = raw_metadata.as_object_mut() {
217→                        if let Some(tx_obj) = tx_fields.as_object() {
218→                            obj.extend(tx_obj.iter().map(|(k, v)| (k.clone(), v.clone())));
219→                        }
220→                        if let Some(rx_obj) = receipt_fields.as_object() {
221→                            obj.extend(rx_obj.iter().map(|(k, v)| (k.clone(), v.clone())));
222→                        }
223→                    }
224→                }
225→            }
226→
227→            let timestamp = i64::try_from(block_timestamp).unwrap_or(i64::MAX);
228→
229→            transactions.push(Transaction {
230→                id: Uuid::new_v4(),
231→                user_id,
232→                wallet_address: wallet.to_string(),
233→                timestamp,
234→                tx_hash,
235→                chain: Chain::Ethereum,
236→                raw_metadata,
237→            });
238→        }
239→
240→        Ok(transactions)
241→    }
242→}
