169→#[async_trait::async_trait]
170→impl ChainIngestor for HyperliquidAdapter {
171→    async fn fetch_history(
172→        &self,
173→        wallet: &str,
174→        limit: usize,
175→        user_id: Uuid,
176→        checkpoint: Option<&IndexerCheckpoint>,
177→    ) -> anyhow::Result<Vec<Transaction>> {
178→        let mut transactions = Vec::new();
179→
180→        // Resume timestamp in milliseconds (HL API uses ms).
181→        // Add 1ms to avoid re-fetching the last seen event.
182→        let resume_ms = checkpoint
183→            .and_then(|cp| cp.last_timestamp)
184→            .map(|ts| (ts * 1000) + 1)
185→            .unwrap_or(0);
186→
187→        // 1. Fetch fills (trades) — the fills endpoint has no startTime param,
188→        //    so we filter client-side.
189→        let fills = self.fetch_user_fills(wallet).await?;
190→        for fill in fills
191→            .iter()
192→            .filter(|f| f.time >= resume_ms as u64)
193→            .take(limit)
194→        {
195→            let raw = serde_json::to_value(fill)?;
196→            transactions.push(Transaction {
197→                id: Uuid::new_v4(),
198→                user_id,
199→                wallet_address: wallet.to_string(),
200→                timestamp: (fill.time / 1000) as i64,
201→                tx_hash: fill.hash.clone(),
202→                chain: Chain::Hyperliquid,
203→                raw_metadata: serde_json::json!({ "type": "fill", "data": raw }),
204→            });
205→        }
206→
207→        // 2. Fetch funding payments
208→        let funding = self.fetch_user_funding(wallet, resume_ms).await?;
209→        for entry in funding.iter().take(limit) {
210→            let raw = serde_json::to_value(entry)?;
211→            let hash = entry
212→                .hash
213→                .clone()
214→                .unwrap_or_else(|| format!("funding-{}-{}", entry.coin, entry.time));
215→            transactions.push(Transaction {
216→                id: Uuid::new_v4(),
217→                user_id,
218→                wallet_address: wallet.to_string(),
219→                timestamp: (entry.time / 1000) as i64,
220→                tx_hash: hash,
221→                chain: Chain::Hyperliquid,
222→                raw_metadata: serde_json::json!({ "type": "funding", "data": raw }),
223→            });
224→        }
225→
226→        // 3. Fetch non-funding ledger updates (deposits, withdrawals, liquidations)
227→        let ledger_updates = self.fetch_user_ledger_updates(wallet, resume_ms).await?;
228→        for update in ledger_updates.iter().take(limit) {
229→            let raw = serde_json::to_value(update)?;
230→            transactions.push(Transaction {
231→                id: Uuid::new_v4(),
232→                user_id,
233→                wallet_address: wallet.to_string(),
234→                timestamp: (update.time / 1000) as i64,
235→                tx_hash: update.hash.clone(),
236→                chain: Chain::Hyperliquid,
237→                raw_metadata: serde_json::json!({ "type": "ledger_update", "data": raw }),
238→            });
239→        }
240→
241→        Ok(transactions)
242→    }
243→}
